// KGS Staff service worker — scope /staff/ ONLY (served from
// www/staff/sw.min.js, so it never controls /app). Shell-only caching:
//   navigations under /staff         → network-first, 3 s timeout, cached shell
//   /assets/trustbit_school_book_seller/staff/ → cache-first (hashed files)
//   /api/*                           → EARLY RETURN — never intercepted or cached
// The version placeholder below is stamped by scripts/postbuild.mjs from the bundle hash, so
// every app change ships a new cache name.

const SW_VERSION = "3d3e86b154ea"
const CACHE = `staff-shell-${SW_VERSION}`
const ASSET_PREFIX = "/assets/trustbit_school_book_seller/staff/"
const SHELL_KEY = "/staff/home"

self.addEventListener("install", () => {
  self.skipWaiting()
})

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys()
      await Promise.all(keys.filter((k) => k.startsWith("staff-shell-") && k !== CACHE).map((k) => caches.delete(k)))
      await self.clients.claim()
    })()
  )
})

self.addEventListener("fetch", (event) => {
  const req = event.request
  if (req.method !== "GET") return
  const url = new URL(req.url)
  if (url.origin !== self.location.origin) return
  if (url.pathname.startsWith("/api/")) return // business data: hands off
  if (url.pathname.startsWith(ASSET_PREFIX)) {
    event.respondWith(cacheFirst(req))
    return
  }
  if (req.mode === "navigate" && url.pathname.startsWith("/staff")) {
    event.respondWith(shellNetworkFirst(req))
  }
})

async function cacheFirst(req) {
  const cache = await caches.open(CACHE)
  const hit = await cache.match(req)
  if (hit) return hit
  const res = await fetch(req)
  if (res && res.ok) cache.put(req, res.clone())
  return res
}

function fetchWithTimeout(req, ms) {
  return new Promise((resolve, reject) => {
    const ctl = new AbortController()
    const timer = setTimeout(() => {
      ctl.abort()
      reject(new Error("timeout"))
    }, ms)
    fetch(req, { signal: ctl.signal }).then(
      (res) => {
        clearTimeout(timer)
        resolve(res)
      },
      (err) => {
        clearTimeout(timer)
        reject(err)
      }
    )
  })
}

async function shellNetworkFirst(req) {
  const cache = await caches.open(CACHE)
  try {
    const res = await fetchWithTimeout(req, 3000)
    if (res && res.ok) cache.put(SHELL_KEY, res.clone())
    return res
  } catch {
    const hit = await cache.match(SHELL_KEY)
    if (hit) return hit
    return new Response("<h1>Offline</h1><p>KGS Staff needs an internet connection.</p>", {
      status: 503,
      headers: { "Content-Type": "text/html" },
    })
  }
}
